162	        String code = owner.getCustomerCode();
163	        if (code == null) {
164	            return null;
165	        }
166	        int sum = 0;
167	        boolean dbl = true;
168	        for (int i = code.length() - 1; i >= 0; i--) {
169	            char c = code.charAt(i);
170	            if (c < '0' || c > '9') {
171	                continue;
172	            }
173	            int d = c - '0';
174	            if (dbl) {
175	                d *= 2;
176	                if (d > 9) {
177	                    d -= 9;
178	                }
179	            }
180	            sum += d;
181	            dbl = !dbl;
182	        }
183	        return (10 - (sum % 10)) % 10;
184	    }
