226	        int points = 0;
227	        if (hasEmail(owner)) {
228	            points += 2;
229	        }
230	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
231	        if (noNamesakes) {
232	            points += 1;
233	        }
234	        if (hasHouseholdBonus(owner)) {
235	            points += 2;
236	        }
237	        if (hasTenureBonus(owner)) {
238	            points += 3;
239	        }
240	        return points;
241	    }
