252	    /**
253	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
254	     * {@link #toMembershipPoints(Owner)}): level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6
255	     * or more.
256	     */
257	    default Integer toMembershipLevel(Owner owner) {
258	        int points = toMembershipPoints(owner);
259	        if (points <= 1) {
260	            return 1;
261	        }
262	        if (points <= 3) {
263	            return 2;
264	        }
265	        if (points <= 5) {
266	            return 3;
267	        }
268	        return 4;
269	    }
270	
271	    /**
272	     * Whether the owner's tenure is at least one elapsed fiscal year, i.e. the fiscal year of the
273	     * current date is later than the fiscal year of the {@code registrationDate} (fiscal years start
274	     * on 1 July; see {@link #fiscalYear(LocalDate)}). A brand-new owner (registered in the current
275	     * fiscal year) has zero elapsed fiscal years and so never qualifies. Returns {@code false} when
276	     * no registration date is present.
277	     */
278	    default boolean hasTenureBonus(Owner owner) {
279	        LocalDate registrationDate = owner.getRegistrationDate();
280	        if (registrationDate == null) {
281	            return false;
282	        }
283	        return fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) >= 1;
284	    }
285	
286	    /**
287	     * Fixed city-to-region table used as the fall-back when deriving an owner's locality.
288	     */
289	    Map<String, String> CITY_REGION = Map.of(
290	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
291	
292	    /**
293	     * Fixed region-to-inclusive-postcode-range table used to derive an owner's locality from the
294	     * postcode: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}}
295	     * inclusive.
296	     */
297	    Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
298	        "NSW", new int[] {2000, 2099},
299	        "VIC", new int[] {3000, 3099},
300	        "QLD", new int[] {4000, 4099});
301	
302	    /**
303	     * Derive an owner's locality (region) from the region-and-hash customer code: the {@code <REGION>}
304	     * segment of the {@code customerCode}, i.e. everything before the first {@code '-'}. Since the
305	     * region is baked into the customer code at creation (see the create endpoint), the locality now
306	     * moves with that identity rather than being recomputed from the postcode and city. When an owner
307	     * has no customer code yet (e.g. legacy records), fall back to deriving the region directly via
308	     * {@link #regionOf(Owner)}.
309	     */
310	    default String toLocality(Owner owner) {
311	        String code = owner.getCustomerCode();
312	        if (code != null) {
313	            int dash = code.indexOf('-');
314	            if (dash > 0) {
315	                return code.substring(0, dash);
316	            }
317	        }
318	        return regionOf(owner);
319	    }
320	
321	    /**
322	     * Fixed region-to-IANA-timezone table used to derive an owner's timezone: NSW -> Australia/Sydney,
323	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane.
324	     */
325	    Map<String, String> REGION_TIMEZONE = Map.of(
326	        "NSW", "Australia/Sydney",
327	        "VIC", "Australia/Melbourne",
328	        "QLD", "Australia/Brisbane");
329	
330	    /**
331	     * Derive an owner's IANA timezone name from its locality/region (see {@link #toLocality(Owner)})
332	     * via the fixed {@link #REGION_TIMEZONE} table. Returns {@code null} when the region resolves to no
333	     * entry in the table (e.g. 'UNKNOWN'), so the timezone is then absent from the DTO.
334	     */
335	    default String toTimezone(Owner owner) {
336	        return REGION_TIMEZONE.get(toLocality(owner));
337	    }
338	
339	    /**
340	     * Derive an owner's region, preferring the postcode: when the postcode is present and falls within
341	     * a known region's range (see {@link #REGION_POSTCODE_RANGES}) that region wins. When the postcode
342	     * is absent or in no known range, fall back to the fixed {@link #CITY_REGION} table. Returns
343	     * 'UNKNOWN' when neither the postcode nor the city resolves a region. This is the region baked into
344	     * the {@code <REGION>} segment of a new owner's customer code and, through it, the owner's locality.
345	     */
346	    default String regionOf(Owner owner) {
347	        // Prefer the postcode: the region whose range contains it wins. The logic is kept here (rather
348	        // than in a String -> String helper) because MapStruct would treat such a helper as an implicit
349	        // type conversion and wrongly apply it to other String properties (e.g. telephone).
350	        String postcode = owner.getPostcode();
351	        if (postcode != null) {
352	            try {
353	                int value = Integer.parseInt(postcode.trim());
354	                for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
355	                    int[] range = entry.getValue();
356	                    if (value >= range[0] && value <= range[1]) {
357	                        return entry.getKey();
358	                    }
359	                }
360	            }
361	            catch (NumberFormatException ignored) {
362	                // Non-numeric postcode: fall back to the city table below.
363	            }
364	        }
365	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
366	    }
367	
368	    Owner toOwner(OwnerDto ownerDto);
369	
370	    @Mapping(target = "id", ignore = true)
371	    @Mapping(target = "pets", ignore = true)
372	    Owner toOwner(OwnerFieldsDto ownerDto);
373	
374	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
375	
376	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
377	
378	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
379	        OwnerPageDto ownerPageDto = new OwnerPageDto();
380	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
381	        ownerPageDto.setPage(ownerPage.getNumber());
382	        ownerPageDto.setSize(ownerPage.getSize());
383	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
384	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
385	        return ownerPageDto;
386	    }
387	}
